<script setup lang="ts">import type{MobileWristband}from'../../types';const props=defineProps<{rows:MobileWristband[];now:number}>();defineEmits<{select:[visitId:string]}>();function elapsed(value:string){const seconds=Math.max(0,Math.floor((props.now-new Date(value).getTime())/1000));return`${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds%3600/60)).padStart(2,'0')}`}</script>
<template><div class="band-list"><button v-for="row in rows" :key="row.visit_id" @click="$emit('select',row.visit_id)"><i :class="row.bath_area"></i><div><strong>{{row.number}} 号</strong><span>{{row.bath_area==='male'?'男浴':'女浴'}} · 已使用 {{elapsed(row.opened_at)}}</span></div><b>¥{{row.amount}}</b><em>›</em></button></div></template>
<style scoped>.band-list{display:grid;gap:10px}button{display:grid;grid-template-columns:8px 1fr auto auto;align-items:center;gap:12px;width:100%;min-height:76px;padding:13px 15px;color:var(--m-text-2);border:1px solid var(--m-border);border-radius:8px;background:white;text-align:left;box-shadow:var(--m-shadow)}i{width:8px;height:44px;border-radius:99px;background:#4a86e8}i.female{background:#d665a3}strong,span{display:block}strong{color:var(--m-text-1);font-size:19px}span{margin-top:4px;color:var(--m-text-3);font-size:11px}b{color:var(--m-danger);font-size:17px}em{color:var(--m-text-3);font-size:26px;font-style:normal}</style>
